const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function stockopolySection(s,i){
 const image=m=>`<figure class="st-art"><img src="/assets/${esc(m.file)}.webp?v=37-stock-layout" alt="${esc(m.alt)}" width="${m.width}" height="${m.height}" ${i===0?'fetchpriority="high"':'loading="lazy"'} decoding="async">${m.caption?`<figcaption>${esc(m.caption)}</figcaption>`:''}</figure>`;
 const flow=s.branches?`<div class="st-flowchart" aria-label="Stockopoly game flow"><div class="st-flow-start"><span>STOCKOPOLY</span><span>Game start</span></div><div class="st-branches">${s.branches.map(([title,nodes])=>`<div class="st-branch"><h3>${esc(title)}</h3><ol>${nodes.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></div>`).join('')}</div><div class="st-loop"><span>Return to the starting square</span><span>A new round begins</span><span aria-hidden="true">↻</span></div></div>`:'';
 return `<section class="wass-section st-section ${esc(s.type)}" ${s.images?.length||s.branches?`id="case-image-${i+1}"`:''}><div class="st-copy"><span class="st-kicker">${esc(s.label)}</span><h2>${esc(s.title)}</h2>${s.text?`<p>${esc(s.text)}</p>`:''}</div>${flow}<div class="st-visuals">${(s.images||[]).map(image).join('')}</div>${s.steps?`<div class="st-steps">${s.steps.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}</section>`;
}
